import{_ as a,o as t,c as n,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"PromptEnhancer: A Simple Approach to Enhance Text-to-Image Models via Chain-of-Thought Prompt Rewriting","description":"","frontmatter":{"title":"PromptEnhancer: A Simple Approach to Enhance Text-to-Image Models via Chain-of-Thought Prompt Rewriting","arxiv":"2509.04545","date":"2025-09-04","authors":"Linqing Wang, Ximing Xing, Yiji Cheng, Zhiyuan Zhao, Donghao Li, Tiankai Hang, Jiale Tao, Qixun Wang, Ruihuang Li, et al.","categories":"cs.CV","topics":"后训练与强化学习, prompt 重写, 奖励模型","outline":[2,2]},"headers":[],"relativePath":"papers/2509.04545.md","filePath":"papers/2509.04545.md","lastUpdated":null}'),e={name:"papers/2509.04545.md"};function r(l,s,o,i,m,c){return t(),n("div",null,[...s[0]||(s[0]=[p('<h1 id="promptenhancer-a-simple-approach-to-enhance-text-to-image-models-via-chain-of-thought-prompt-rewriting" tabindex="-1">PromptEnhancer: A Simple Approach to Enhance Text-to-Image Models via Chain-of-Thought Prompt Rewriting <a class="header-anchor" href="#promptenhancer-a-simple-approach-to-enhance-text-to-image-models-via-chain-of-thought-prompt-rewriting" aria-label="Permalink to &quot;PromptEnhancer: A Simple Approach to Enhance Text-to-Image Models via Chain-of-Thought Prompt Rewriting&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2509.04545" target="_blank" rel="noreferrer">2509.04545</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-09-04（本页依据 v5，2025-09-23）</td></tr><tr><td><strong>作者</strong></td><td>Linqing Wang, Ximing Xing, Yiji Cheng, Zhiyuan Zhao, Donghao Li, Tiankai Hang, Jiale Tao, Qixun Wang, Ruihuang Li, et al.（Tencent Hunyuan，项目负责人 Chunyu Wang，通讯 Qinglin Lu）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 prompt 重写器从生成器里彻底拆出来，用一个按 24 条细粒度 key point 打分的奖励模型 AlignEvaluator 做 GRPO，训出一个对任何冻结 T2I 模型都能即插即用的 CoT 改写器。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/post-training-rl">后训练与强化学习</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>用户实际输入的 prompt 通常只有一句话，而 T2I 扩散模型真正吃得下的是一段结构化的、把主体、属性、空间关系、风格逐层展开的长描述。这中间的落差造成一类稳定复现的失败：属性绑定错位（&quot;穿蓝衣的男人和穿黄衣的女人&quot;两件衣服互换）、否定被忽略（&quot;牛肉面，不要葱&quot;照样撒葱）、计数失准（&quot;四条狗&quot;给出三条或五条）、复合关系崩塌（&quot;形状像吉他的湖&quot;退化成湖边放一把吉他）。</p><p>绕开这个落差有两条路。一条是改生成器：用更好的 caption 重新训练模型，DALL-E 3 的 recaptioning 就是代表。这条路要求你有生成器的权重与训练算力，并且每换一个底座就得重做一遍。另一条是改输入：在 prompt 进入生成器之前先把它扩写好。后者的吸引力在于成本，但此前一直没被做扎实，原因见 §2。</p><p>这篇论文的价值主张很直接：把改写器训成一个独立组件，训练时用一个冻结的 T2I 模型（HunyuanImage 2.1）当环境，训完之后这个改写器理论上可以挂在任何 T2I 模型前面。对于工程团队来说，这等于把&quot;对齐&quot;这件事从模型权重里搬到了模型外面，换底座不需要重训。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>**Recaptioning 路线（DALL-E 3）**已经证明了&quot;更好的文本描述能显著提升 prompt following&quot;，但它把改写能力烧进了生成器权重，属于生成器侧的一次性投资。</p><p><strong>迭代式 refinement 与 automatic prompt engineering</strong>（论文点名 Hao 等的 prompt optimization、BeautifulPrompt、Mañas 等）用 LLM 在循环里批评并修订 prompt。它们的奖励信号通常是 CLIP score 或通用人类偏好分（ImageReward、HPSv2）。论文对这类信号的批评很具体：这些分数只给出图文相似度的一个粗粒度标量，<strong>没有能力指出错在哪一条</strong>。当模型把&quot;四条狗&quot;画成三条时，CLIP score 会略微下降，但下降幅度和&quot;风格不对&quot;造成的下降混在一起，梯度里区分不出来。</p><p><strong>Agent 化系统</strong>（多模态 LLM 规划 + 布局约束 + 分步渲染）在组合性上确实有提升，但论文指出它们普遍把 reasoner 和某个特定 T2I 架构紧耦合，换生成器要重做工程。</p><p><strong>细粒度评测基准</strong>（T2I-CompBench、EvalMuse）已经把&quot;属性绑定&quot;&quot;空间关系&quot;这些维度拆开测了，但它们停留在<strong>测量</strong>层面。论文自述的差异点就在这里：把细粒度评测从被动的度量工具变成主动的训练信号。</p><p>需要说清楚的是，前人不是&quot;没想到&quot;要用细粒度奖励，而是缺一个覆盖面足够宽、标注量足够大的细粒度打分模型。这篇论文的主要工程投入正是造这个模型。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在 2025 年中，已知的事实有三条：GRPO 在 LLM 上被证明可以用一个标量奖励稳定地对齐策略；T2I 模型的失败模式已经被基准工作系统整理过；把短 prompt 扩写成长 prompt 确实有效，这一点从 DALL-E 3 的 recaptioning 与各家线上产品的&quot;prompt 优化&quot;按钮都能看到。</p><p>顺着这三条往下推，第一个问题是：既然扩写有效，为什么不直接用 GPT-4 类通用模型扩写就完事？答案是通用 LLM 不知道 T2I 模型的具体脾气——它会把 prompt 写得文学化、抒情、含糊，而 T2I 需要的是把每个实体的属性钉死。要让改写器学到&quot;T2I 特有的语法&quot;，就得有一个能判定&quot;这次改写有没有让生成图更符合原意&quot;的裁判。</p><p>第二个问题是：裁判用什么？如果用 CLIP score 或通用偏好分，梯度里全是&quot;好看/不好看&quot;，改写器最容易学到的策略是往 prompt 里堆美学形容词，而不是修正属性绑定。所以裁判必须能分维度打分。于是问题转化为：需要一个覆盖 T2I 全部常见失败模式的分类体系，以及按这个体系标注的大规模数据。</p><p>第三个问题是格式。要让改写器&quot;先分析后改写&quot;，直接 RL 从零学太慢，先用一个强教师模型（Gemini-2.5-Pro / DeepSeek-V3）蒸馏出 CoT 格式，再用 RL 去调质量，这是 LLM 后训练的标准两段式。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>短 prompt 到图像之间的失败，绝大多数是<strong>语义歧义</strong>造成的，而歧义是可以在文本层面被显式消除的。既然如此，就不必动生成器，只需要在生成器前面放一个知道 T2I 会在哪 24 个地方翻车的改写器。让这个改写器学会 T2I 的偏好的关键，是给它一个能分辨&quot;哪一条错了&quot;的裁判——一个只会说&quot;整体像不像&quot;的裁判会把改写器推向堆砌辞藻，一个会说&quot;数量错了、否定丢了、属性绑反了&quot;的裁判才会把它推向精确。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>整个框架有两个可训练组件：CoT Rewriter（策略模型，从 Hunyuan-7B-Instruct 初始化）和 AlignEvaluator（奖励模型）。T2I 生成器 HunyuanImage 2.1 全程冻结。</p><p><strong>T2I-KeyPoints 分类体系</strong>是全篇的地基：24 个细粒度 key point，归到 6 个超类。以论文表 1 给出的例子说明——语言理解类含否定（&quot;牛肉面，不要葱&quot;）、属性一致性（&quot;五个人都穿红衣&quot;）、代词消解（&quot;大球撞碎了桌子因为它是金属做的&quot;，&quot;它&quot;指球）；视觉属性类含计数（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span>）、尺寸、材质、表情；动作交互类含全身动作（&quot;托马斯全旋&quot;）、手部动作（&quot;用筷子夹菜&quot;）、接触交互、非接触交互（&quot;爱因斯坦看着霍金&quot;）；关系结构类含比较关系、组合关系（&quot;橘子瓣拼成的猫&quot;）、包含关系、相似关系（&quot;形状像吉他的湖&quot;）、跨实体绑定、实体布局；再加上世界知识与反事实、图中文字与文字排版。每条 key point 还标了判定口径是文图一致性（TIC）还是结构完整性（SI）。</p><p><strong>SFT 数据流水线</strong>：从 326 万张图（153 万中文向、173 万英文向）出发，用 captioning 模型生成短描述，得到 226 万条代理用户 prompt；用 Gemini-2.5-Pro 对每条 prompt 生成 CoT 推理链与多个候选 reprompt；用 Gemini-2.5-Pro 自动过滤语义偏移、信息丢失、语句不通的样本，从 100 万条降到 611,921 条三元组；再用 Hunyuan T2I 把候选 reprompt 渲染成图，由专业标注员挑出最符合用户意图的那一条，最终得到 <strong>485,119</strong> 条（user prompt, CoT, reprompt）三元组。这里有一处口径不整齐值得记下：§3.1 开头把四个阶段的顺序写成&quot;模拟 → 生成 → 人工挑选 → 自动过滤&quot;，而下面的编号列表实际顺序是&quot;模拟 → 生成 → 自动过滤 → 人工挑选&quot;；同时&quot;226 万条代理 prompt&quot;与&quot;从 100 万条过滤到 611,921 条&quot;之间的收缩过程论文没有交代。</p><p><strong>RL prompt 集</strong>：另取约 5 万条 prompt，源图与 SFT 完全不相交，无 ground-truth CoT/reprompt，学习信号全部来自 AlignEvaluator 在线打分。</p><p><strong>GRPO 训练环</strong>：对每条用户 prompt，改写器采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 个候选 reprompt → 冻结的 HunyuanImage 2.1 各生成一张图 → AlignEvaluator 对每个 (原始 prompt, 生成图) 对给一个标量奖励 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> → 用组内相对优势更新策略。</p><p><strong>超参</strong>：全程 8 张 H800。SFT 学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、cosine、warmup 0.1、有效 batch 128（每卡 8 × 梯度累积 2 × 8 卡）、bfloat16；GRPO 学习率降到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span></span>、常数调度、有效 batch 64、rollout <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、KL 系数 0.001。<strong>epoch 数在论文内部自相矛盾</strong>：正文 §5.2 两处都写&quot;10 epochs&quot;，而同节的表 2 写 SFT 2 epoch、GRPO 1 epoch。</p><p><strong>评测基准</strong>：作者另发布 T2I-Keypoints-Align，共 6,687 条 prompt（英文 3,000 条占 44.9%，中文 3,687 条占 55.1%），每条标注多个 key point 类别。中英文分布差异明显：中文 prompt 长度均值约 100 字符、key point 密度峰值在 4；英文长度均值约 500 字符、密度在 3 到 6 之间较均匀。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文正文没有给出 GRPO 的形式化目标函数，只以引用形式沿用 Shao 等的原始定义，并用文字描述训练环。为便于理解奖励结构，这里补一句背景：GRPO 不学 value function，而是对同一 prompt 采样一组输出，用组内奖励的相对排名构造优势</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.363em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mord mathrm">std</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mop"><span class="mord mathrm">mean</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span></span></span></span></span></p><p>再配 KL 惩罚约束策略不要跑离 SFT 初始化太远。本文对应的取值是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span>、KL 系数 0.001。<strong>需要明确标注</strong>：上式是 GRPO 的通用形式，论文本身<strong>没有</strong>写出这个公式，也没有说明 AlignEvaluator 的 24 维分数是如何聚合成标量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的（等权求和、加权、还是学出来的头，正文均未交代）。这是本文形式化程度上的一个真实缺口。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题</strong>：把改写器插在冻结的 HunyuanImage 2.1 前面，prompt following 能提升多少，提升在哪些维度上。</p><p><strong>设计</strong>：在自建的 T2I-Keypoints-Align 上，对 24 个语义类别分别统计&quot;有改写器&quot;与&quot;无改写器&quot;的准确率，报告逐类的百分点差值与绝对分数（图 9）。</p><p><strong>结论</strong>：24 个维度的平均准确率提升 <strong>+5.1%</strong>，20/24 个类别有正向提升，15 个类别提升超过 5.0 个百分点。提升最大的集中在需要组合与抽象推理的类别：相似关系 +17.3%、反事实 +17.2%、计数 +15.0%、代词消解 +13.9%、表情 +12.0%、跨实体绑定 +11.3%。接触交互与尺寸持平（+0.0%），艺术风格几乎不动（+0.9%），作者解释为底座本来就够好。有两个类别退步：文字排版 -0.7%、非接触交互 -0.9%，作者归因为改写过程对简单概念可能引入过度指定。</p><p><strong>这一节的证据强度必须诚实说明</strong>。论文只做了 with/without 的单一对比，缺三样东西：(1) 没有任何<strong>改写器 baseline</strong>——没有和 GPT-4 直接改写、和作为教师的 Gemini-2.5-Pro 直接改写、和 BeautifulPrompt 一类已有方法对比。这一条最要命，因为 SFT 数据就是 Gemini-2.5-Pro 蒸馏出来的，&quot;7B 学生 vs 教师本人&quot;的对比是读者第一个会问的问题。(2) 没有 <strong>SFT-only vs SFT+GRPO 的消融</strong>，因此无法判断 +5.1% 里有多少来自 GRPO、多少仅仅来自&quot;prompt 变长了&quot;。(3) 图 9 的准确率<strong>由谁判定，论文全文没有说明</strong>——正文没有描述人工评测协议（评测员数量、打分口径、一致性），摘要里承诺的 &quot;human preference benchmark&quot; 在实验节也没有兑现成一张人评表。如果这些准确率是由 AlignEvaluator 自己打的，那么训练信号与评测指标同源，+5.1% 就有相当部分可能是奖励模型自评的产物。<strong>论文没有给出足以排除这一解释的信息。</strong></p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：T2I 的 prompt following 失败大多可以在文本侧修复，前提是有一个知道&quot;错在哪一条&quot;的裁判。作者把常见失败模式整理成 24 条 key point、6 个超类，据此训了奖励模型 AlignEvaluator。改写器先用 Gemini-2.5-Pro 蒸馏的 48.5 万条 CoT 数据做 SFT，再用 GRPO 以 AlignEvaluator 为奖励做对齐，全程 T2I 权重冻结。在自建的 6,687 条基准上，24 维平均准确率 +5.1%，组合与抽象推理类涨幅最大。但论文没有对比任何其他改写器、没有做 SFT/GRPO 消融、也没有说明准确率的判定主体。</p><p><strong>3 句话版</strong>：把 prompt 改写从生成器里解耦出来，用 24 维细粒度奖励模型做 GRPO 训练一个 CoT 改写器。在冻结的 HunyuanImage 2.1 上，24 个语义维度平均提升 5.1 个百分点，相似关系、反事实、计数涨幅最大。真正的贡献是那套 24 条失败模式分类学与配套标注，而不是 GRPO 本身。</p><p><strong>1 句话版</strong>：用细粒度、可分维度的奖励模型把&quot;prompt 工程&quot;训成一个可复用的模型外挂。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>AlignEvaluator 的打分是 T2I 对齐质量的可信代理</strong>。整篇论文的因果链是&quot;改写器最大化 AlignEvaluator 的分 → 图像更符合用户意图&quot;，中间没有独立锚点。</p><p>它在实践中可能不成立的理由很具体。AlignEvaluator 是一个在（reprompt, image）对上按 24 条 key point 训出来的模型，本身会有系统性偏差；而 GRPO 是一个专门用来最大化奖励的算法，reward hacking 是它的默认失败模式而非例外。改写器完全可能学会一类&quot;讨好评价器&quot;的写法——例如把数量词重复三遍、把否定改写成正面枚举——这类写法在 AlignEvaluator 上得分高，在人眼看来却是 prompt 变得冗长呆板。</p><p>论文为这条假设提供的证据是不足的：<strong>没有报告 AlignEvaluator 与人类判断的一致性（相关系数、Kappa、或任何校准曲线）</strong>，也没有报告 GRPO 训练过程中奖励曲线与独立人评的分离情况。KL 系数 0.001 是唯一的防护，但它只约束策略不要跑离 SFT 太远，不约束奖励本身是否正确。要让这个 claim 站住，最低限度需要一张&quot;AlignEvaluator 分数 vs 人类偏好&quot;的校准散点，以及在 GRPO 不同 checkpoint 上的人评曲线。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内、不需要复现整套系统的最小验证，目标是<strong>把&quot;改写有效&quot;与&quot;这个改写器有效&quot;分开</strong>。</p><ul><li><strong>数据</strong>：从公开的 T2I-Keypoints-Eval（作者已在 HuggingFace 释出）里抽 300 条 prompt，覆盖计数、否定、跨实体绑定、相似关系四个高涨幅类别，每类 75 条。</li><li><strong>实现</strong>：四个 arm，全部接同一个开源 T2I 底座（用 FLUX.1-dev 或 SDXL，不必是 HunyuanImage）。arm A：原始 prompt 直出；arm B：让 GPT-4 类通用 LLM 用一段通用扩写指令改写；arm C：作者开源的 PromptEnhancer 权重改写；arm D：机械扩写对照——把原 prompt 复读一遍并追加固定的风格后缀（用来估计&quot;仅仅变长&quot;的收益）。每条 prompt 每 arm 生成 4 张，固定随机种子。</li><li><strong>测量</strong>：不使用 AlignEvaluator。用两个独立口径：(i) 针对每条 prompt 手写一个二元判定问题（&quot;图中恰好有四条狗吗&quot;），用一个与训练无关的 VLM 回答；(ii) 抽 100 条做人工二元判定，用来校准 (i) 的 VLM 判定准确率，并报告这个校准数字。</li><li><strong>判定标准</strong>：若 C 显著优于 B 且优于 D（配对 bootstrap，95% 区间不含 0），支持&quot;专用改写器 &gt; 通用 LLM 改写&quot;这一核心 claim；若 C ≈ B，则论文的 +5.1% 主要说明&quot;扩写有用&quot;而非&quot;这个改写器有用&quot;；若 C ≈ D，说明收益主要来自 prompt 变长。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是构造一个<strong>评价器同源性检验</strong>。</p><p>取论文的评测集，把每条 prompt 的判定同时交给三方：AlignEvaluator、一个与训练完全无关的强 VLM、以及人类标注员。在这三套判定下分别重算 with/without 的 24 维准确率。反对者的预测是：AlignEvaluator 口径下的提升最大，独立 VLM 口径下明显收窄，人类口径下进一步收窄，且退步的类别数会增加。如果这个梯度真的出现，那么 +5.1% 的相当部分就是&quot;奖励模型自评&quot;的产物，而非对齐质量的真实改善。论文当前没有提供任何数据能排除这个替代解释。</p><p>第二个攻击面是<strong>可预测的失败条件</strong>：论文自己承认文字排版和非接触交互退步了。这两类的共同点是原 prompt 中的约束是<strong>位置性</strong>或<strong>关系性</strong>且已经写得很明确，扩写只会稀释它。据此可以设计一个&quot;高约束密度&quot;子集——每条 prompt 都是短句、约束明确、无歧义（&quot;红色圆圈在蓝色方块正上方&quot;）——预测改写器在这个子集上整体退步。如果成立，说明该方法的收益来源是消除歧义，而不是提升生成器能力，那么它在 prompt 已经足够精确的专业用户场景里是负收益。</p><p>第三个角度是<strong>跨底座泛化</strong>。&quot;universal / model-agnostic&quot;是论文的核心卖点，但全部实验只在 HunyuanImage 2.1 上做。改写器是通过 GRPO 在这个特定生成器的响应上训出来的，它学到的很可能是 HunyuanImage 2.1 的偏好而非通用的 T2I 语法。把同一个改写器挂到 SDXL 或 FLUX 上重测，是对&quot;universal&quot;这个词最直接的证伪实验，而论文没有做。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：本文把&quot;对齐&quot;外置成了一个改写器，但奖励仍然是一个把 24 维压成标量的黑箱，改写器不知道自己修的是哪一条。同时评测与奖励同源，无法自证。</p><p><strong>新的 framing</strong>：把改写从&quot;生成一段更好的文本&quot;改成<strong>在结构化语义图上做可验证编辑</strong>。让改写器输出的不是自然语言长句，而是一个显式的场景图——实体、属性、关系、计数、否定作用域——再由确定性模板渲染成给 T2I 的文本。这样每一次改写都变成图上的一组可枚举操作（新增属性节点、绑定属性到实体、把否定转成排他约束）。</p><p><strong>可借鉴的相邻工具</strong>：语义解析与可执行程序合成里的&quot;程序即中间表示&quot;思想，以及形式化验证里的约束求解。有了场景图，&quot;图里是不是恰好四条狗&quot;就不再需要一个奖励模型来判断，而可以由一个在生成图上跑的检测器 + 计数器给出<strong>可独立校准</strong>的判定，从而彻底切断&quot;训练信号与评测指标同源&quot;这条循环。</p><p><strong>第一个实验</strong>：只做计数与否定两类。为 500 条 prompt 手工标注 ground-truth 场景图，训一个 prompt → 场景图的解析器，用模板渲染成文本喂给冻结 T2I，然后用开放词表检测器数目标数量。先报告检测器本身在人工标注上的准确率（这是必须先做的校准），再报告&quot;结构化改写 vs 自由文本改写 vs 原始 prompt&quot;三者的计数正确率。假如结构化路线在计数上明显胜出而在美学分上不劣，就说明把改写变成可验证操作是一条比端到端 RL 更可靠的路径。</p>',58)])])}const u=a(e,[["render",r]]);export{h as __pageData,u as default};
